async def cleanup(self) -> None:
    """Cleanup all resources (recording and persistence)"""
    await self.stop_recording()
    await self._stop_persistence()

    # Close LiveKit client if it exists
    if self._livekit_client:
        try:
            # LiveKitAPI uses httpx internally which needs to be closed
            if hasattr(self._livekit_client, 'aclose'):
                await self._livekit_client.aclose()
            elif hasattr(self._livekit_client, 'close'):
                await self._livekit_client.close()
            self._livekit_client = None
            logger.debug("Closed LiveKit API client")
        except Exception as e:
            logger.error(f"Error closing LiveKit client: {e}")

